#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Walks the captain through the parts of Google Workspace access only he can do:
# the Cloud console, the OAuth consent, and one sign-in per account. Everything a
# script can do on its own - directories, permissions, MCP registration, the exact
# invocation - is delegated to bin/fm-google-workspace.sh, which owns those contracts.
# Safe to stop and re-run: every stage is idempotent and reports what already exists.
#
# This wizard never displays a token, a refresh token, or a client secret, and it
# never deletes or replaces a stored credential.

TOTAL_STAGES=11

FM="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/fm-google-workspace.sh"
[[ -x "$FM" ]] || { printf 'error: %s is missing\n' "$FM" >&2; exit 1; }

"$FM" init >/dev/null || { printf 'error: cannot prepare the credentials directories\n' >&2; exit 1; }
GWS_ROOT="$("$FM" paths | awk -F': +' '$1 == "root" { print $2 }')"
ENV_FILE="$GWS_ROOT/setup.env"

# fail reports a stage that did not complete, without ending the run: the captain can
# fix the cause and re-run, and later stages still print what they need.
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; SKIPPED+=("$1"); }

# authorize_account runs one attended consent ceremony and its verifying read.
# The account that actually signed in is reported back, so a wrong-account sign-in
# is caught here rather than at first use.
authorize_account() {
  local account="$1" label="$2"
  stage "Authorize $account"
  say "One sign-in for $label. Each account gets its own private credential store,"
  say "so this must be repeated once per account - there is no shared login."
  note "credentials: $("$FM" paths "$account" | awk -F': +' '$1 == "credentials dir" { print $2 }')"
  printf '\n'
  step "A browser window will open on Google's sign-in page."
  step "Sign in as $account. If another account is already signed in, switch to this one."
  step "Approve every permission it asks for; a missing one silently disables a tool later."
  warn "You will see an 'unverified app' screen: choose Advanced, then Continue."
  note "That warning is expected. The app is yours and Google does not require review for personal use."
  printf '\n'
  pause "Ready to sign in as $account?"
  printf '\n'
  note "The first sign-in also downloads the Google Workspace tool, so it can take a minute."
  if "$FM" auth "$account"; then
    printf '  %s✓ %s is authorized and answering%s\n' "$GREEN" "$account" "$RESET"
  else
    fail "$account was not authorized; re-run this wizard to retry that account"
  fi
  printf '\n'
  pause "Continue?"
}

banner "Google Workspace access for Arjun's three accounts"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: the project"
say "All three accounts share one Cloud project and one OAuth client."
say "Reuse an existing project or make a new one - either is fine."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project (a name like 'arjun-workspace-agents' is plenty), or pick an existing one."
step "Copy its Project ID - the lowercase id, not the display name."
ask GCP_PROJECT_ID "Paste the project ID:"
if [[ -n "$GCP_PROJECT_ID" ]]; then
  write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
else
  fail "no project ID captured; the console links in the next stages will not preselect a project"
fi
pause "Continue?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: enable exactly six APIs"
say "Six APIs, no more. Each one is a service the agents were authorized for;"
say "anything else enabled here widens the blast radius for no benefit."
printf '\n'
for api in gmail drive calendar docs sheets people; do
  step "Enable the ${api} API"
  open_url "https://console.cloud.google.com/apis/library/${api}.googleapis.com?project=${GCP_PROJECT_ID}"
  pause "Enabled ${api}? Press Enter for the next one."
done
note "People API is the one behind Contacts; its library entry is named People, not Contacts."
pause "All six enabled?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: the consent screen"
say "This is what you will see when signing in, and it decides how long logins last."
open_url "https://console.cloud.google.com/auth/overview?project=${GCP_PROJECT_ID}"
step "If asked to configure the consent screen, do it now."
step "User type: External. Internal is impossible here - two of these accounts are personal."
step "App name: anything you will recognise, e.g. 'Arjun agents'. Support email: your own."
step "Publishing status: Publish app, so it is In production, NOT Testing."
warn "Left in Testing, every login expires after 7 days and all three accounts must be redone weekly."
note "Google does not require verification for personal use; the unverified warning screen is the whole cost."
pause "Consent screen configured and published?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: the Desktop OAuth client"
say "One Desktop client serves all three accounts. Desktop is required:"
say "it is the type that allows the local loopback sign-in these tools use."
open_url "https://console.cloud.google.com/auth/clients/create?project=${GCP_PROJECT_ID}"
step "Application type: Desktop app. Name it anything."
step "Create it, then click Download JSON and save the file."
printf '\n'
ask CLIENT_SECRET_DOWNLOAD "Paste the path to the downloaded JSON (e.g. ~/Downloads/client_secret_....json):"
CLIENT_SECRET_DOWNLOAD="${CLIENT_SECRET_DOWNLOAD/#\~/$HOME}"
if "$FM" client-secret import "$CLIENT_SECRET_DOWNLOAD"; then
  say "Installed private to your user, readable by nobody else, and outside every repo."
  if confirm "Delete the copy in your Downloads folder?"; then
    rm -- "$CLIENT_SECRET_DOWNLOAD" && say "Removed the download."
  else
    warn "The download is still on disk; move or delete it yourself when convenient."
  fi
else
  fail "the OAuth client JSON was not installed; nothing else will work until it is"
fi
pause "Continue?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Bitwarden: keep a copy of the client credentials"
say "The client file above is the one thing here you cannot regenerate without redoing"
say "stage 4. Bitwarden holds the durable copy; it is never committed anywhere."
printf '\n'
if BWS_ACCESS_TOKEN="${BWS_ACCESS_TOKEN:-}" "$FM" client-secret status | grep -q '^bws token:     available'; then
  "$FM" client-secret push-bws || fail "could not store the client credentials in Bitwarden"
else
  say "This machine has no Bitwarden access token configured, so nothing can be stored yet."
  say "You can paste a machine-account token now, or skip and do it later."
  ask_secret BWS_TOKEN_INPUT "Bitwarden access token (or press Enter to skip):"
  if [[ -n "$BWS_TOKEN_INPUT" ]]; then
    if BWS_ACCESS_TOKEN="$BWS_TOKEN_INPUT" "$FM" client-secret push-bws; then
      if confirm "Save that token for future runs (private to your user)?"; then
        mkdir -p "$HOME/.config/bws"
        ( umask 077 && printf '%s' "$BWS_TOKEN_INPUT" > "$HOME/.config/bws/access-token" )
        chmod 0600 "$HOME/.config/bws/access-token"
        say "Saved. It is readable by nobody else and was never displayed."
      fi
    else
      fail "Bitwarden rejected that token; the client credentials are still only on this machine"
    fi
  else
    SKIPPED+=("store the OAuth client in Bitwarden: run '$FM client-secret push-bws' once a token is set")
    warn "Skipped. The client file is on this machine only - back it up before you rely on it."
  fi
fi
unset BWS_TOKEN_INPUT
pause "Continue?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "ecomills.com: the one account that can be blocked"
say "arjun@ecomills.com is a Workspace account, so its domain admin can restrict"
say "third-party apps. The other two are personal accounts and cannot be blocked this way."
printf '\n'
say "You do not need to do anything yet. If the ecomills sign-in later refuses outright -"
say "blocked rather than warning about an unverified app - that restriction is the cause."
note "The fix is in the Workspace Admin console, as an admin of ecomills.com:"
note "  Security > Access and data control > API controls > Trusted by OAuth client ID,"
note "  then trust the client ID from stage 4."
pause "Understood?"

# ── 7, 8, 9 ───────────────────────────────────────────────────────────────
authorize_account arjmad@gmail.com "your personal account"
authorize_account arjun@ecomills.com "your Ecomills work account"
authorize_account williamkempf@gmail.com "the Kempf account"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Wire it into Claude Code"
say "Registers the three accounts so every Claude Code session on this machine can"
say "reach them, each through its own separate connection."
printf '\n'
if "$FM" claude-install; then
  say "Done. Restart any Claude Code session that is already open to pick them up."
else
  fail "could not register the accounts with Claude Code; run '$FM claude-install' to retry"
fi
printf '\n'
"$FM" status
printf '\n'
pause "Continue?"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Hand the same wiring to Cade"
say "Cade's configuration lives in his own repository, so this wizard will not edit it."
say "The block below is exactly what belongs under mcp_servers in cade/config/config.yaml."
printf '\n'
"$FM" hermes-config
printf '\n'
note "Cade shares these same three logins, so he needs no sign-in of his own."
SKIPPED+=("add the block above to cade/config/config.yaml, then run ./check.sh and ./deploy.sh --apply-config")
pause "Noted?"

finish
